// Block (composition) — the step that waits for a card: the amount, what to do with the card, a
// picture of where on this device, and a way out. A POS (in a dialog), a counter, a payment terminal and a
// kiosk each show it, each with its own copy for the same three acts.
//
// The copy is keyed, not free: `prompts` holds one string per method a product uses, set once per
// locale, and `method` picks one; a method without its own string falls back to `any`. A product that
// says 「카드를 끝까지 넣어주세요」 on one device and 「카드를 꽂아주세요」 on another fixes it in one place.
//
// `media` is the device's own picture (where its slot or reader is), so one device is never drawn on
// another. It is decorative: the title says what to do. `notice` is a change the person must hear while
// waiting (「IC칩을 읽지 못했어요. 카드를 긁어주세요」 after a failed insert). It is a polite live region
// that stays in the accessibility tree while empty, so its first message is announced; the same message
// set twice is not announced again unless it is cleared or changed between.
//
// The reader's timeout and its warning (WCAG 2.2.1, 고시 2.b) are the consumer's. Do not count seconds
// in `notice`: a polite region would announce every tick.
//
// It arranges StepHeader, the media slot, the notice and an outline cancel Button; `size` reaches all of
// them, the cancel included, because the size axis is forwarded, never chosen per control.
import { useId } from "react";
import type { ReactNode, Ref } from "react";
import { Button } from "../components/Button";
import { StepHeader } from "../components/StepHeader";
import { Stack } from "../layouts/Stack";
import "./CardPrompt.css";

export type CardMethod = "insert" | "tap" | "swipe" | "any";

/** The prompt per method: `any` always, the others as the product uses them. */
export type CardPromptCopy = { any: string } & Partial<Record<Exclude<CardMethod, "any">, string>>;

export interface CardPromptBaseProps {
  /**
   * Size of the header type and the cancel Button. `large` on a customer device.
   *
   * @default "large"
   */
  size?: "small" | "medium" | "large";
  /**
   * Header alignment: `center` on a customer screen, `start` in a staff dialog. `start` also sets the
   * cancel at the start, hugging its label, instead of centred.
   *
   * @default "center"
   */
  align?: "start" | "center";
  /**
   * Heading level of the prompt: 1 when the step is the whole screen, 2 inside a dialog or panel.
   *
   * @default 2
   */
  level?: 1 | 2 | 3;
  /** The amount line above the prompt, e.g. "결제할 금액 14,500원". */
  amount?: ReactNode;
  /**
   * Which way the card is to be presented.
   *
   * @default "any"
   */
  method?: CardMethod;
  /** The prompt for each method. */
  prompts: CardPromptCopy;
  /** A line under the prompt, e.g. the installment or a reminder. */
  description?: ReactNode;
  /** The device's picture of where to present the card. Decorative. */
  media?: ReactNode;
  /** A change announced while waiting, e.g. a failed IC read. Pass `null` to clear it. */
  notice?: ReactNode;
}

export type CardPromptProps = CardPromptBaseProps &
  (
    | {
        /** Label of the cancel Button. */
        cancelLabel: string;
        /** Called when the person cancels. */
        onCancel: () => void;
      }
    | { cancelLabel?: undefined; onCancel?: undefined }
  ) & {
    /** Additional class (optional). sd-card-prompt is always preserved. */
    className?: string;
    /** Forwarded to the root element. */
    ref?: Ref<HTMLElement>;
  };

export function CardPrompt({
  size = "large",
  align = "center",
  level = 2,
  amount,
  method = "any",
  prompts,
  description,
  media,
  notice,
  cancelLabel,
  onCancel,
  className,
  ref,
}: CardPromptProps) {
  const headingId = useId();
  const justify = align === "center" ? "center" : "start";
  return (
    <Stack
      as="section"
      ref={ref}
      gap="large"
      align={justify}
      aria-labelledby={headingId}
      className={className ? `sd-card-prompt ${className}` : "sd-card-prompt"}
    >
      {/* The notice qualifies the prompt, so it sits with the header, not out by the cancel. */}
      <div className="sd-card-prompt__head-inset">
        <Stack gap="small" className="sd-card-prompt__head">
          <div className="sd-card-prompt__header">
            <StepHeader
              id={headingId}
              size={size}
              align={align}
              level={level}
              eyebrow={amount}
              title={prompts[method] ?? prompts.any}
              description={description}
            />
          </div>
          {/* spacing: attachment — the notice qualifies the prompt above it */}
          <p className={`sd-card-prompt__notice sd-type-body-${size}`} data-align={align} aria-live="polite">
            {notice}
          </p>
        </Stack>
      </div>
      {media != null && (
        <div className="sd-card-prompt__media" aria-hidden="true">
          {media}
        </div>
      )}
      {/* spacing: attachment — the cancel acts on the wait above it */}
      {cancelLabel !== undefined && (
        <Button variant="secondary" size={size} onPress={onCancel}>
          {cancelLabel}
        </Button>
      )}
    </Stack>
  );
}

/* Layout only (block-contract.md §3, §5): Stack places the head, the picture and the cancel; the
   picture takes the space left so it stays large on a tall customer screen. */
.sd-card-prompt {
  inline-size: 100%;
  block-size: 100%;
}

.sd-card-prompt__head-inset {
  align-self: stretch;
}

.sd-card-prompt__media {
  display: grid;
  place-items: center;
  flex: 1;
  min-block-size: 0;
}

.sd-card-prompt__notice {
  margin: 0;
}

.sd-card-prompt__notice[data-align="center"] {
  text-align: center;
}

/* Empty, the notice leaves the flow but stays in the accessibility tree, so its first message is
   announced (a region that enters the tree with its text often is not). */
.sd-card-prompt__notice:empty {
  position: absolute;
}
